package io.cascadeshield.sim;

import com.fasterxml.jackson.databind.ObjectMapper;
import java.util.*;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
import static io.cascadeshield.sim.Models.*;
import static io.cascadeshield.sim.OpsModels.*;
import static io.cascadeshield.sim.BenchmarkModels.*;

/** Artificial topology for software assertions only, never research acquisition data. */
class CounterfactualExperimentEngineTest {
    static final ObjectMapper M=new ObjectMapper().findAndRegisterModules();
    static final Point A=new Point(80.25,13.05),B=new Point(80.2505,13.05),C=new Point(80.251,13.05),D=new Point(80.2505,13.0505);
    static RoadGraph roads(){List<Node>nodes=List.of(new Node(1,A.longitude(),A.latitude()),new Node(2,B.longitude(),B.latitude()),new Node(3,C.longitude(),C.latitude()),new Node(4,D.longitude(),D.latitude()));return new RoadGraph(new NetworkFile("COUNTERFACTUAL_UNIT_TEST_ONLY","Artificial software fixture",List.of(13d,80d,14d,81d),nodes,List.of(edge("AB",1,2,50,10,nodes),edge("BC",2,3,50,20,nodes),edge("AD",1,4,70,30,nodes),edge("DC",4,3,40,40,nodes),edge("BD",2,4,40,50,nodes)),List.of(),Map.of("provenance","TEST_FIXTURE_ONLY")));}
    static Edge edge(String id,long from,long to,double len,long way,List<Node>nodes){return new Edge(id,id,from,to,way,len,36,"TEST_FIXTURE_ONLY","residential",id,List.of(nodes.get((int)from-1).point().coordinates(),nodes.get((int)to-1).point().coordinates()),Map.of());}
    static TruckSpec truck(String id,double depart){return new TruckSpec(id,id,A,C,List.of(),36,1000,500,"Simulated driver","NORMAL",depart,1000);}
    static SimulationEngine fixture(boolean second,boolean spare){SimulationEngine e=new SimulationEngine(roads(),M);e.addTruck(truck("A",0));if(second)e.addTruck(truck("B",20));e.resource("warehouses",new WarehouseSpec("W","Simulated warehouse",C,spare?2:1),true);e.resource("docks",new DockSpec("D1","Dock one","W",40,0,1000),true);if(spare)e.resource("docks",new DockSpec("D2","Spare dock","W",40,0,1000),true);e.resource("drivers",new DriverSpec("DR1","Driver one",true,0,1000),true);e.resource("drivers",new DriverSpec("DR2","Driver two",true,0,1000),true);e.resource("deliveries",new DeliverySpec("L1","Delivery one","W",200,100,"NORMAL"),true);if(second)e.resource("deliveries",new DeliverySpec("L2","Delivery two","W",200,100,"HIGH"),true);e.assign(new AssignmentSpec("A","DR1","D1",List.of("L1"),10,50));if(second)e.assign(new AssignmentSpec("B","DR2","D1",List.of("L2"),50,90));return e;}
    static CounterfactualExperimentEngine cf(){return new CounterfactualExperimentEngine(roads(),M);}
    static Action find(CounterfactualExperimentEngine cf,State s,String truck,ActionType type){return cf.actions(s,truck).stream().filter(a->a.type()==type).findFirst().orElseThrow();}
    static Action action(ActionType type,String truck,List<String>ids){return new Action("fixture",type,truck,0,null,0,0,ids,"Software test action");}

    @Test void executedAlternativesNeverChangeLiveStateOrOriginalOutcome(){SimulationEngine live=fixture(true,true);live.addIncident(new IncidentRequest("CLOSURE","AB",1,15,0d));var before=M.valueToTree(live.raw());CounterfactualExperimentEngine cf=cf();Rollout none=cf.trial(live.raw(),find(cf,live.raw(),"B",ActionType.NONE),200);Rollout dock=cf.trial(live.raw(),cf.actions(live.raw(),"B").stream().filter(a->a.type()==ActionType.ADJUST_DOCK_RESERVATION&&"D2".equals(a.dockId())).findFirst().orElseThrow(),200);assertEquals(before,M.valueToTree(live.raw()));assertTrue(none.valid());assertEquals(2,none.metrics().completedDeliveries());assertEquals(5,none.metrics().totalDeliveryLatenessSec(),1e-7);assertEquals(0,dock.metrics().totalDeliveryLatenessSec(),1e-7);assertEquals("MODEL_ROLLOUT_FORECAST",dock.metrics().provenance());assertEquals(0,live.raw().clockSec);assertEquals(-1,live.raw().operations.deliveries.getFirst().deliveredAtSec);}
    @Test void replayFutureAndDerivedEtaAreRemovedFromCurrentKnowledge(){SimulationEngine live=fixture(false,false);live.raw().trucks.getFirst().departureSec=20;live.addIncident(new IncidentRequest("CLOSURE","AB",1,60,20d));live.raw().replaySchedule.add(new ScheduledCommand(25,90,"DRIVER_AVAILABILITY",Map.of("id","DR1","available",false)));live.refresh(true);assertTrue(live.truck("A").etaSec>30);State observed=cf().observedClone(live.raw());assertTrue(observed.incidents.isEmpty());assertTrue(observed.replaySchedule.isEmpty());assertTrue(observed.commandHistory.isEmpty());assertFalse(observed.replaying);assertEquals(30,observed.trucks.getFirst().etaSec,1e-7);assertTrue(observed.trucks.getFirst().affectedIncidentIds.isEmpty());assertTrue(observed.operations.cascade.nodeRisks().stream().allMatch(r->r.causeIds().stream().noneMatch(c->c.contains("I001"))));}
    @Test void unavailableDriverHasNoImaginedFutureRestoration(){SimulationEngine live=fixture(false,false);live.availability("DR1",false);live.raw().replaySchedule.add(new ScheduledCommand(20,1,"DRIVER_AVAILABILITY",Map.of("id","DR1","available",true)));CounterfactualExperimentEngine cf=cf();Rollout result=cf.trial(live.raw(),find(cf,live.raw(),"A",ActionType.NONE),200);assertEquals(0,result.metrics().completedDeliveries());assertEquals(1,result.metrics().unfinishedDeliveries());assertEquals(1,result.metrics().slaViolationRate());assertTrue(result.metrics().recoveryCensored());assertEquals(-1,result.finalState().trucks.getFirst().arrivalSec);assertEquals(0,result.finalState().trucks.getFirst().distanceTravelledM);}
    @Test void hiddenSchedulesCannotChangeCounterfactualChoices(){SimulationEngine live=fixture(true,true);live.addIncident(new IncidentRequest("CLOSURE","AB",1,15,0d));CounterfactualExperimentEngine cf=cf();Action none=find(cf,live.raw(),"B",ActionType.NONE);Rollout first=cf.trial(live.raw(),none,200);live.raw().replaySchedule.add(new ScheduledCommand(30,2,"DRIVER_AVAILABILITY",Map.of("id","DR2","available",false)));live.raw().commandHistory.add(new ScheduledCommand(0,3,"INCIDENT_ADD",Map.of("physicalId","BC","startSec",40d)));Rollout second=cf.trial(live.raw(),none,200);assertEquals(first.metrics(),second.metrics());assertEquals(first.knowledgeFingerprint(),second.knowledgeFingerprint());}
    @Test void localAndGlobalRoutesExecuteDifferentConnectedRepairs(){SimulationEngine live=fixture(false,false);live.addIncident(new IncidentRequest("CLOSURE","BC",1,30,0d));CounterfactualExperimentEngine cf=cf();Action local=find(cf,live.raw(),"A",ActionType.LOCAL_REROUTE),global=find(cf,live.raw(),"A",ActionType.GLOBAL_REROUTE);assertEquals(List.of("AB","BD","DC"),local.routeEdgeIds());assertEquals(List.of("AD","DC"),global.routeEdgeIds());Rollout l=cf.trial(live.raw(),local,200),g=cf.trial(live.raw(),global,200);assertEquals(130,l.metrics().travelDistanceM(),1e-7);assertEquals(110,g.metrics().travelDistanceM(),1e-7);assertEquals(13,l.finalState().trucks.getFirst().arrivalSec,1e-7);assertEquals(11,g.finalState().trucks.getFirst().arrivalSec,1e-7);assertEquals(1,l.metrics().totalReroutes());}
    @Test void occupiedEdgePrefixAndPositionArePreservedDuringReroute(){SimulationEngine live=fixture(false,false);live.advance(25);live.addIncident(new IncidentRequest("CLOSURE","BC",1,30,null));CounterfactualExperimentEngine cf=cf();Action route=find(cf,live.raw(),"A",ActionType.GLOBAL_REROUTE);assertEquals("AB",route.routeEdgeIds().getFirst());State copy=cf.observedClone(live.raw());SimulationEngine branch=new SimulationEngine(roads(),M);branch.restore(copy);List<Double>position=List.copyOf(branch.truck("A").position);double offset=branch.truck("A").offsetM;cf.apply(branch,route);assertEquals(position,branch.truck("A").position);assertEquals(offset,branch.truck("A").offsetM);assertEquals("AB",branch.truck("A").route.edgeIds().getFirst());CounterfactualExperimentEngine.advanceTo(branch,200);assertEquals(130,branch.truck("A").distanceTravelledM,1e-7);}
    @Test void disconnectedOrTeleportingRouteIsRejected(){SimulationEngine live=fixture(false,false);CounterfactualExperimentEngine cf=cf();assertTrue(cf.validate(live.raw(),action(ActionType.GLOBAL_REROUTE,"A",List.of("BC"))).stream().anyMatch(Violation::hard));live.advance(10);assertTrue(cf.validate(live.raw(),action(ActionType.GLOBAL_REROUTE,"A",List.of("AD","DC"))).stream().anyMatch(Violation::hard));}
    @Test void legalTurnRestrictionsRejectForgedRoute(){RoadGraph base=roads();RoadGraph restricted=new RoadGraph(new NetworkFile(base.network.networkId(),"Restricted fixture",base.network.bbox(),base.network.nodes(),base.network.edges(),List.of(new Restriction(10,2,50,"no_right_turn")),Map.of()));SimulationEngine live=new SimulationEngine(restricted,M);live.addTruck(truck("A",0));CounterfactualExperimentEngine cf=new CounterfactualExperimentEngine(restricted,M);assertTrue(cf.validate(live.raw(),action(ActionType.LOCAL_REROUTE,"A",List.of("AB","BD","DC"))).stream().anyMatch(v->v.hard()&&v.code().equals("CONNECTED_ROUTE")));}
    @Test void driverDutyWindowRejectsOtherwiseConnectedLongerRoute(){SimulationEngine live=fixture(false,false);OperationalRuntime.driver(live.raw(),"DR1").shiftEndSec=10.5;live.addIncident(new IncidentRequest("CLOSURE","BC",1,30,0d));assertTrue(cf().validate(live.raw(),action(ActionType.GLOBAL_REROUTE,"A",List.of("AD","DC"))).stream().anyMatch(v->v.hard()&&v.code().equals("DRIVER_SHIFT")));}
    @Test void assignedCapacityAndWarehouseReferencesAreHardConstraints(){SimulationEngine live=fixture(false,false);live.truck("A").capacityKg=100;assertTrue(cf().validate(live.raw(),action(ActionType.NONE,"A",List.of())).stream().anyMatch(v->v.hard()&&v.code().contains("CAPACITY")));}
    @Test void overlappingOrClosedDockReservationsAreRejected(){SimulationEngine live=fixture(true,true);Action overlapping=new Action("overlap",ActionType.ADJUST_DOCK_RESERVATION,"B",0,"D1",20,60,List.of(),"Overlap fixture");assertTrue(cf().validate(live.raw(),overlapping).stream().anyMatch(v->v.hard()&&v.code().equals("DOCK_RESERVATION")));Action closed=new Action("closed",ActionType.ADJUST_DOCK_RESERVATION,"B",0,"D2",980,1020,List.of(),"Closing fixture");assertTrue(cf().validate(live.raw(),closed).stream().anyMatch(Violation::hard));}
    @Test void unloadingCannotBeTeleportedToSpareDock(){SimulationEngine live=fixture(false,true);live.advance(110);assertEquals("UNLOADING",OperationalRuntime.assignment(live.raw(),"A").status);Action move=new Action("move",ActionType.ADJUST_DOCK_RESERVATION,"A",0,"D2",20,60,List.of(),"Already occupied fixture");assertTrue(cf().validate(live.raw(),move).stream().anyMatch(Violation::hard));}
    @Test void deadlineViolationsAreMeasuredSoftConstraints(){SimulationEngine live=fixture(false,false);OperationalRuntime.delivery(live.raw(),"L1").deadlineSec=20;CounterfactualExperimentEngine cf=cf();Action wait=new Action("wait",ActionType.WAIT,"A",10,null,0,0,List.of(),"Soft deadline fixture");assertTrue(cf.validate(live.raw(),wait).stream().anyMatch(v->!v.hard()&&v.code().equals("SLA_DEADLINE")));Rollout r=cf.trial(live.raw(),wait,200);assertTrue(r.valid());assertEquals(1,r.metrics().slaViolations());assertEquals(40,r.metrics().totalDeliveryLatenessSec(),1e-7);}
    @Test void sameObservedInputsProduceDeterministicPhysicalOutcomes(){SimulationEngine live=fixture(true,true);live.addIncident(new IncidentRequest("CLOSURE","AB",1,15,0d));CounterfactualExperimentEngine cf=cf();Action none=find(cf,live.raw(),"A",ActionType.NONE);Rollout a=cf.trial(live.raw(),none,200),b=cf.trial(live.raw(),none,200);assertEquals(a.metrics(),b.metrics());assertEquals(M.valueToTree(a.finalState().operations),M.valueToTree(b.finalState().operations));assertEquals(a.knowledgeFingerprint(),b.knowledgeFingerprint());}
    @Test void shorterHorizonKeepsPrematureDeliveriesCensored(){SimulationEngine live=fixture(false,false);CounterfactualExperimentEngine cf=cf();Rollout r=cf.trial(live.raw(),find(cf,live.raw(),"A",ActionType.NONE),20);assertEquals(0,r.metrics().completedDeliveries());assertEquals(1,r.metrics().unfinishedDeliveries());assertEquals(1,r.metrics().slaViolations());assertEquals(0,r.metrics().totalDeliveryLatenessSec());assertTrue(r.metrics().recoveryCensored());assertEquals(-1,r.finalState().operations.deliveries.getFirst().deliveredAtSec);}
    @Test void normalizationUsesOnlyFeasibleCurrentAlternativesAndFiniteScores(){SimulationEngine live=fixture(false,true);live.addIncident(new IncidentRequest("CLOSURE","BC",1,30,0d));CounterfactualExperimentEngine cf=cf();List<Rollout>results=cf.actions(live.raw(),"A").stream().map(a->cf.trial(live.raw(),a,200)).toList();for(ScoredAlternative s:cf.score(results))assertTrue(Double.isFinite(s.score()));Action chosen=cf.choose(results);assertTrue(results.stream().anyMatch(r->r.valid()&&r.action().equals(chosen)));assertEquals(1,CounterfactualExperimentEngine.WEIGHTS.values().stream().mapToDouble(Double::doubleValue).sum(),1e-9);}
    @Test void fewerCensoredDeliveriesDominatesCheaperAlternative(){SimulationEngine live=fixture(false,false);CounterfactualExperimentEngine cf=cf();Rollout done=cf.trial(live.raw(),find(cf,live.raw(),"A",ActionType.NONE),200);Action stalled=new Action("stalled",ActionType.WAIT,"A",200,null,0,0,List.of(),"Censor fixture");Rollout censored=cf.trial(live.raw(),stalled,200);assertEquals(0,censored.metrics().completedDeliveries());assertEquals(done.action(),cf.choose(List.of(censored,done)));}
    @Test void metricsUseUniqueResourcesSignedDistanceAndExplicitCostUnits(){SimulationEngine live=fixture(true,false);live.addIncident(new IncidentRequest("CLOSURE","AB",1,15,0d));State start=live.snapshot();CounterfactualExperimentEngine.advanceTo(live,200);Metrics m=ExperimentMetrics.measure(start,live.raw(),200,0,0,7,0);assertEquals(2,m.completedDeliveries());assertEquals(1,m.slaViolations());assertEquals(.5,m.slaViolationRate());assertEquals(5,m.totalDeliveryLatenessSec(),1e-7);assertEquals(0,m.signedAdditionalDistanceM(),1e-7);assertEquals(0,m.positiveAdditionalDistanceM(),1e-7);assertTrue(m.downstreamAffectedResources()>=1);assertEquals(105,m.recoveryTimeSec(),1e-7);assertEquals(7,m.decisionComputationMs());assertEquals("SIMULATED_RESEARCH_EXPERIMENT",m.provenance());}
    @Test void unsupportedResourceTransfersAreNotInActionVocabulary(){assertFalse(Arrays.stream(ActionType.values()).anyMatch(a->a.name().contains("DRIVER")||a.name().contains("VEHICLE")||a.name().contains("PRIORITY")));}
    @Test void rerouteSearchUsesActualDepartureAfterClearingApprovedWait(){SimulationEngine live=fixture(false,false);live.addIncident(new IncidentRequest("CLOSURE","BC",1,30,0d));live.truck("A").waitUntilSec=30;live.truck("A").approvedWaitIncidentIds.add("I001");CounterfactualExperimentEngine cf=cf();Action global=find(cf,live.raw(),"A",ActionType.GLOBAL_REROUTE);assertEquals(List.of("AD","DC"),global.routeEdgeIds());Rollout r=cf.trial(live.raw(),global,200);assertEquals(11,r.finalState().trucks.getFirst().arrivalSec,1e-7);}
    @Test void invalidOrFractionalHorizonsAreRejectedInsteadOfSilentlyRounded(){SimulationEngine live=fixture(false,false);CounterfactualExperimentEngine cf=cf();Action none=find(cf,live.raw(),"A",ActionType.NONE);assertThrows(ApiException.class,()->cf.trial(live.raw(),none,Double.NaN));assertThrows(ApiException.class,()->cf.trial(live.raw(),none,10.07));live.advance(10);assertThrows(ApiException.class,()->cf.runObserved(live.raw(),.5));}
    @Test void physicalAuditAcceptsActualSafeQueueServiceAndCompletedOutcomes(){SimulationEngine live=fixture(true,false);live.addIncident(new IncidentRequest("CLOSURE","AB",1,15,0d));CounterfactualExperimentEngine cf=cf();assertTrue(cf.audit(live.raw()).isEmpty());for(int i=0;i<110;i++){live.advance(10);assertTrue(cf.audit(live.raw()).isEmpty(),()->cf.audit(live.raw()).toString());}}
    @Test void physicalAuditMeasuresCapacityPositionAndConnectedRouteFailures(){SimulationEngine live=fixture(false,false);live.truck("A").loadKg=2000;live.truck("A").position=D.coordinates();Set<String>codes=cf().audit(live.raw()).stream().map(Violation::code).collect(java.util.stream.Collectors.toSet());assertTrue(codes.contains("AUDIT_CAPACITY"));assertTrue(codes.contains("AUDIT_POSITION"));live.truck("A").route=roads().describe(List.of("AB","DC"),A,C,36);assertTrue(cf().audit(live.raw()).stream().anyMatch(v->v.code().equals("AUDIT_ROUTE")));}
    @Test void physicalAuditMeasuresAssignmentAndDeliveryOwnershipFailures(){SimulationEngine live=fixture(false,false);OperationalRuntime.delivery(live.raw(),"L1").truckId="OTHER";OperationalRuntime.assignment(live.raw(),"A").driverId="ABSENT";List<Violation>audit=cf().audit(live.raw());assertTrue(audit.stream().anyMatch(v->v.code().equals("AUDIT_ASSIGNMENT_REFERENCE")));OperationalRuntime.assignment(live.raw(),"A").driverId="DR1";audit=cf().audit(live.raw());assertTrue(audit.stream().anyMatch(v->v.code().equals("AUDIT_DELIVERY_REFERENCE")));}
    @Test void physicalAuditMeasuresActualServiceOpeningAndOverlapViolations(){SimulationEngine live=fixture(true,false);Assignment a=OperationalRuntime.assignment(live.raw(),"A"),b=OperationalRuntime.assignment(live.raw(),"B");a.actualDockStartSec=10;a.actualDockEndSec=50;b.actualDockStartSec=30;b.actualDockEndSec=70;live.raw().clockSec=30;OperationalRuntime.dock(live.raw(),"D1").openUntilSec=60;List<Violation>audit=cf().audit(live.raw());assertTrue(audit.stream().anyMatch(v->v.code().equals("AUDIT_DOCK_OVERLAP")));assertTrue(audit.stream().anyMatch(v->v.code().equals("AUDIT_DOCK_WINDOW")));}
    @Test void physicalAuditIsReadOnlyAndKeepsRejectedProposalsSeparate(){SimulationEngine live=fixture(true,false);CounterfactualExperimentEngine cf=cf();var before=M.valueToTree(live.raw());assertTrue(cf.audit(live.raw()).isEmpty());assertTrue(cf.validate(live.raw(),action(ActionType.GLOBAL_REROUTE,"A",List.of("BC"))).stream().anyMatch(Violation::hard));assertTrue(cf.audit(live.raw()).isEmpty());assertEquals(before,M.valueToTree(live.raw()));}
    @Test void rolloutCountsMeasuredInvariantFailuresOnceInsteadOfCandidateRejections(){SimulationEngine live=fixture(true,false);live.truck("B").loadKg=2000;CounterfactualExperimentEngine cf=cf();Rollout r=cf.trial(live.raw(),find(cf,live.raw(),"A",ActionType.NONE),200);assertFalse(r.valid());assertEquals(1,r.metrics().constraintViolations());assertTrue(r.violations().stream().anyMatch(v->v.code().equals("AUDIT_CAPACITY")));}
}
